practice => [
{ t => 'Your boundary opener', p => 'Write your two boundary questions for your next pairing session, plus one navigator question you commit to asking at least once.', a => q{The committed navigator question matters more than the boundaries — it converts you from passenger to participant. "Why not the naive approach first?" fits almost any session; so does "what would make this fail in production?"} },
{ t => 'Debrief in one page', p => 'Shadow your next senior meeting with three declared watch-points. Write the debrief the same day — one of the three lines must be a "skipped slides" class observation.', a => q{The skipped-slides line requires watching for absence, not presence: what did the expert NOT do? Not answered, not presented, not defended. Absence observations are the ones insiders can no longer see.} },
