grammar => [
['The modal ladder as register', q{<em>"Personal data must be processed lawfully."</em>, <em>"may only be shared where there is a lawful basis."</em> — compliance English grades rules by modal: <strong>must</strong> (regulator), <strong>shall</strong> (policy), <strong>should</strong> (practice), <strong>may</strong> (permission). Learn to read the ladder, and you can hear the severity of any rule in the bank by its auxiliary verb alone.}, q{"Personal data must be processed lawfully."、"may only be shared where there is a lawful basis."——合规英语按情态动词给规则分级：<strong>must</strong>（监管）、<strong>shall</strong>（政策）、<strong>should</strong>（实践）、<strong>may</strong>（许可）。学会读阶梯，仅凭助动词就能听出银行任何规则的严重程度。}],
['The citation sentence', q{<em>"I can share this once we have a lawful basis on record — the form takes two minutes, and I can start it now."</em> — grammar of the helpful refusal: [can, conditionally] + [the rule, quoted lightly] + [the mechanism] + [motion]. Notice there is no "you cannot" anywhere — the modal "can" appears with its condition instead. This is how banks say no while sounding like yes-with-a-step.}, q{"I can share this once we have a lawful basis on record — the form takes two minutes, and I can start it now."——有助益的拒绝语法：[有条件的 can] + [轻引用规则] + [机制] + [行动]。注意通篇没有"you cannot"——情态动词 "can" 带着条件出现。这就是银行"拒绝却听起来像带一步的是"的说话方式。}],
],
tips => [
q{<strong>Do not speed-click.</strong> Two modules are better written than your team\'s docs, and the register inside is the one your audits will use.},
q{<strong>Build the sentence bank.</strong> One sentence per module, chosen for future use: the lawful-basis reply, the appearance test, the gifts-register decline.},
q{<strong>Learn the modal ladder once, use it for years.</strong> must / shall / should / may — you will hear severity levels in every policy meeting after.},
q{<strong>Refusals carry citations.</strong> "Because compliance says so" creates friction; "once we have a lawful basis on record" creates motion.},
q{<strong>The appearance test changes behaviour.</strong> It is stricter than reality — the nice dinner fails it, and now you have the exact sentence for why.},
],
practice => [
{ t => 'Start your sentence bank', p => 'From your next mandatory module, harvest three sentences: one must, one should, one may. For each, write the day-to-day situation where you would say it.', a => q{The situation column is the real exercise — "may only be shared where there is a lawful basis" becomes live the first time a client asks for data. Compliance sentences without a situation attached are trivia; with one, they are tools.} },
{ t => 'The polite decline', p => 'A vendor offers you concert tickets during a tender. Write your decline using the citation sentence structure: appreciation, rule quoted lightly, register name, alternative offered.', a => q{Model: "I genuinely appreciate it — but during a live tender, anything that could appear to influence a decision has to sit out. The gifts register does not cover tender-season tickets. Coffee after the award, on me, is a different story." Warmth intact, citation intact.} },
{ t => 'Modal audit', p => 'Take your own last three work emails. Which modals did you use for requests — and would "should" or "must" have changed how they landed?', a => q{Most new joiners over-use "must" (reading as demanding) or under-use it (reading as optional). The ladder works in both directions: choosing the modal deliberately is choosing how much authority your sentence claims.} },
],
